/* Compile with: gcc -o timer_example timer_example.c -lrt */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

timer_t g_timerid;

// Signal handler function executes when timer expires
void timer_handler(int sig, siginfo_t *si, void *uc) {
    printf("\n[Handler] Timer ID %p expired. Exiting.\n", si->si_value.sival_ptr);
    // Clean up and exit gracefully
    timer_delete(g_timerid);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigevent sev;
    struct sigaction sa;
    struct itimerspec its;

    // 1. Setup signal handling (using a real-time signal)
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Setup sigevent: notify via SIGRTMIN
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    // Pass the timer ID handle to the signal handler
    sev.sigev_value.sival_ptr = &g_timerid;

    // 3. Create the timer using CLOCK_MONOTONIC
    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timerid) == -1) {
        perror("timer_create");
        return EXIT_FAILURE;
    }
    printf("Timer created (ID: %p)\n", (void*)g_timerid);

    // 4. Arm the timer: fire after 1.5 seconds, one-shot
    its.it_value.tv_sec = 1;
    its.it_value.tv_nsec = 500000000; // 0.5 seconds
    its.it_interval.tv_sec = 0; // Set interval to zero for one-shot timer
    its.it_interval.tv_nsec = 0;

    if (timer_settime(g_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        timer_delete(g_timerid);
        return EXIT_FAILURE;
    }
    printf("Timer armed. Waiting for signal...\n");

    // Wait for the signal delivery
    pause(); 

    // Unreachable if handler exits, but good practice if not exiting:
    // timer_delete(g_timerid);
    return EXIT_SUCCESS;
}
